class Solution {
  void main() {
    var input = Stdin.readLineSync();
    if (input == null) return;

    int n = int.parse(input);
    List<int> a = [];
    for (int i = 0; i < n; i++) {
      String line = Stdin.readLineSync().trim();
      while (line.isEmpty && Stdin.hasMoreLines) line = Stdin.readLineSync().trim();
      a.addAll(line.split(' ').map(int.parse));
    }

    List<List<String>> grid = buildGrid(n, a);

    print(grid.length);
    for (var row in grid) {
      stdout.write(row.join(" "));
      stdout.writeln("");
    }
  }

  static List<List<String>> buildGrid(int n, List<int> nums) {
    List<List<String>> rows = [List.filled(n, ' ')];

    for (int k = 1; k <= n; k++) {
      List<int> pos = [];
      for (int j = 0; j < n - k + 1; j++) {
        pos.add(nums[j]);
      }

      for (int j = 0; j < pos.length; j++) {
        int idx = n - 2 * (k - 1) + j;
        rows[idx][j] = pos[j].toString();
      }
    }

    return rows;
  }
}

