int _nextPrime(int last) {
  int candidate = last + 1;
  while (true) {
    bool isPrime = true;
    for (int divisor = 2; divisor * divisor <= candidate; divisor++) {
      if (candidate % divisor == 0) {
        isPrime = false;
        break;
      }
    }
    if (isPrime) return candidate;
    candidate++;
  }
}

