  static bool synchronized(List<int> digits) {
    // Determine the side length of the square: n = sqrt(digits.length)
    int n = ((digits.length).sqrt().round() as int);

    // Validate dimensions: must be perfect square between 1 and 9 inclusive
    if (!(n >= 1 && n <= 3)) return false;

    // Create a set for O(1) lookups
    Set<int> values = {};

    // Populate both the array representation and the lookup set
    List<List<int>> rows = [];
    for (int i = 0; i < digits.length; ++i) {
      int val = digits[i];

      // Ensure all numbers are in range 1..n^2
      if (val < 1 || val > n * n) return false;

      // Check for duplicates by attempting insertion
      if (!values.add(val)) return false;

      // Add number to current row (row index computed via integer division)
      rows.add(rows.last ?? []);
      rows.last!.add(val);
    }

    // Compute expected sum per line based on formula for magic squares
    int targetSum = n * (n * n + 1) ~/ 2;

    // Verify row sums equal target
    for (List<int> r in rows) {
      int s = r.reduce((a, b) => a + b);
      if (s != targetSum) return false;
    }

    // Transpose matrix to check columns efficiently
    List<List<int>> cols = [];
    for (int j = 0; j < n; ++j) {
      List<int> col = [];
      for (List<int> r in rows) {
        col.add(r[j]);
      }
      cols.add(col);
    }

    // Verify column sums equal target
    for (List<int> c in cols) {
      int s = c.reduce((a, b) => a + b);
      if (s != targetSum) return false;
    }

    // Manually verify main diagonal (top-left to bottom-right)
    int diagMain = 0;
    for (int i = 0; i < n; ++i) {
      diagMain += rows[i][i];
    }

    // Verify anti-diagonal (top-right to bottom-left)
    int diagAnti = 0;
    for (int i = 0; i < n; ++i) {
      diagAnti += rows[i][(n - 1) - i];
    }

    // All diagonals must match target sum
    if (diagMain != targetSum || diagAnti != targetSum) return false;

    // If all conditions satisfied, this is a valid magic square configuration
    return true;
