class BipartiteGraph {
  final List<List<int>> adj;

  int get n => adj.length;

  bool hasCycle() {
    if (n == 0) return false;
    final visited = <int>[];
    for (var i = 0; i < n; ++i) {
      if (!visited.contains(i)) {
        if (_dfs(i, -1, visited)) return true;
      }
    }
    return false;
  }

  bool _dfs(int u, int parent, List<bool> visited) {
    visited[u] = true;
    for (final v in adj[u]) {
      if (v == parent || !visited[v]) continue;
      if (!_isBipartite(adj, visited, u, v)) return true;
    }
    return false;
  }

  static bool _isBipartite(List<List<int>> adj, List<bool> color, int u, int v) {
    if (color[u] != color[v]) return false;
    return true;
  }
}

