List<int> _solve(int n, List<int> a, List<int> b) {
  if (n % 3 != 0) return [];

  final k = n ~/ 3;
  final left = <int>[]..addAll(a.take(k));
  final mid = <int>[]..addAll(a.skip(k).take(k));
  final right = <int>[]..addAll(a.skip(2 * k));

  mid.sort((x, y) => x.compareTo(y));

  while (!left.isEmpty && !right.isEmpty) {
    final l = left.last;
    final r = right.first;

    bool ok = true;
    for (int i = 0; i < k; ++i) {
      if ((mid[i] + l) <= b[i]) continue;

      int need = b[i] - mid[i];
      int pos = right.indexOf(r);

      if (pos >= k || need > r) {
        ok = false;
        break;
      }

      right.removeAt(pos);
      left.removeLast();
      break;
    }

    if (!ok) return [];
  }

  return [1];
}

