List<Point> convexHull(List<Point> pts) {
  if (pts.length <= 1) return List.of(pts);
  pts.sort((a,b) => a.x == b.x ? a.y.compareTo(b.y) : a.x.compareTo(b.x));
  List<Point> hull = [];

  for (var p in pts) {
    while (hull.length >= 2 && cross(hull[hull.length-2], hull.last, p) <= 0) {
      hull.removeLast();
    }
    hull.add(p);
  }

  int n = hull.length;
  if (n > 3) {
    for (int i = n-2; i >= 0; --i) {
      var t = hull[i];

      while (cross(hull[0], hull[n-1], t) < 0) {
        hull.removeRange(n-1..);
        hull.insertAll(0, [t]);
      }
    }
  } else {
    hull.clear();

    for (int i = 0; i < n; ++i) {
      var t = hull[i];

      while (cross(hull[(i+1)%n], hull[(i+n+1)%n], t) < 0) {
        hull.removeAt(i);

        if (i < hull.length) {
          break;
        }
      }
    }
  }

  return List.unmodifiable(hull);
}

