    const int UNVISITED = -1;
    final List<int> color = List.filled(_adjacencyList.length, UNVISITED);

    for (int i = 0; i < _adjacencyList.length; ++i) {
      if (color[i] == UNVISITED) {
        Queue<int> queue = Queue();
        color[i] = 0;
        queue.add(i);

        while (queue.isNotEmpty) {
          int node = queue.removeFirst();

          for (final edge in _adjacencyList[node]) {
            int neighbor = edge.v;

            if (color[neighbor] == UNVISITED) {
              color[neighbor] = 1 - color[node];
              queue.add(neighbor);
            } else if (color[neighbor] == color[node]) {
              return false;
            }
          }
        }
      }
    }

    return true;
  }
}

