class Graph {
  final List<List<int>> _adj = [];

  void addEdge(int u, int v) => _adj[u] ??= [], _adj[v] ??= [], 
      (_adj[u].add(v)..removeWhere((v2) => v == v2));

  bool hasCycle() {
    const n = this._adj.length;
    if (n == 0) return false;
    final visited = <int>[];
    final stack = [0];
    while (stack.isNotEmpty) {
      final top = stack.last;
      if (!visited.contains(top)) {
        for (final nb in _adj[top]!) {
          if (!visited.contains(nb)) {
            stack.add(nb);
            break; // Jump to next iteration of the outer loop.
          } else if (nb != top && !(_adj[nb]!.contains(top))) {
            return true;
          }
        }
        visited.add(top);
        stack.removeLast();
      }
    }
    return false;
  }
}

