void main() {
  final List<String> lines = File('input.txt').readLinesSync();
  int n = lines.length;

  if (n != 3) {
    print("Error: Exactly 3 lines required");
    return;
  }

  // Parse numbers from each line into a list of integers
  final List<List<int>> grid = <List<int>>[];
  for (int i = 0; i < n; i++) {
    String rowStr = lines[i].trim().split(' ').join();
    List<int> row = rowStr.split('').map((char) => char.codeUnitAt(0)).toList();
    grid.add(row);
  }

  // Solve the problem using backtracking to find maximum path sum
  int maxSum = -1;

  void backtrack(int r, int c, int currentSum) {
    if (r == n && c == n) {
      if (currentSum > maxSum) {
        maxSum = currentSum;
      }
      return;
    }

    int nextR = r + 1;
    int nextC = c + 1;

    bool validDown = nextR >= 0 && nextR < n && 
                     (nextC == c || abs(nextC - c) <= 2);
    bool validRight = nextC >= 0 && nextC < n && 
                      (abs(r - nextR) <= 2);

    // Move down
    if (validDown) {
      int newSum = currentSum + grid[nextR][c];
      backtrack(nextR, c, newSum);
    }

    // Move right
    if (validRight) {
      int newSum = currentSum + grid[r][nextC];
      backtrack(r, nextC, newSum);
    }
  }

  // Start from top-left corner with initial value
  backtrack(0, 0, grid[0][0]);

  print(maxSum);
}

