String ShuntingYard.toPostfix(String input) {
  final tokens = input.trim().split(' ');
  final output = <String>[];
  final stack = <String>[];

  for (final token in tokens) {
    if (_isOperand(token)) {
      output.add(token);
    } else if (_isOperator(token, '(', ')')) {
      _handleParentheses(stack, token, output);
    } else if (_isOperator(token, '+', '-', '*', '/')) {
      while (!_isEmpty(stack) && 
             priority(_peek(stack), token) >= 0) {
        output.add(stack.removeLast());
      }
