int priority(String op1, String op2) {
  int p1, p2;
  switch (op1) {
    case '(': p1 = -1; break;
    case '+':
    case '-': p1 = 1; break;
    case '*':
    case '/': p1 = 2; break;
    default: p1 = 3; // Parenthesis or unknown
