  switch (op2) {
    case '(': p2 = -1; break;
    case '+':
    case '-': p2 = 1; break;
    case '*':
    case '/': p2 = 2; break;
    default: p2 = 3;
  }
  return p1 > p2 ? 1 : p1 <= p2 ? 0 : -1;
}

