      int count = 0;
      for (int k = 0; k <= 6; ++k) {
        if (arr[i + k] == maxDigit) {
          ++count;
        }
      }
      if (count > 1) break;
    }
    bool valid = true;
    for (int k = 0; k <= 6; ++k) {
      if ((arr[i + k] == 0 || arr[i + k] == 1) && !valid) break;
      if (arr[i + k] > 0) valid &= arr[k] == arr[i + k];
    }
